					const isTemp = await this.tcLayer.isTempContainer(t.cookieStoreId)
					console.log(`[PCT] reopen: ${poll} — Check B: tab ${t.id} url=${t.url} cookieStoreId=${t.cookieStoreId} isTemp=${isTemp}`)
