			removeAll: vi.fn().mockResolvedValue(undefined),
			onClicked: { addListener: vi.fn() },
		},
		tabs: {
			create: vi.fn().mockResolvedValue({ id: 99, index: 1, cookieStoreId: 'firefox-container-2' }),
